/* ---------------------------------------------------------------
   Storage shim: the Claude artifact environment provides a global
   window.storage API (get/set/delete/list) for persistence.
   Outside that environment, this calls the /api/storage serverless
   function (backed by Supabase) — so all visitors and the admin
   dashboard share the same real data.
--------------------------------------------------------------- */
if (typeof window !== "undefined" && !window.storage) {
  const base = "/api/storage";
  window.storage = {
    async get(key) {
      const res = await fetch(`${base}?key=${encodeURIComponent(key)}`);
      if (!res.ok) throw new Error("not found");
      const data = await res.json();
      return { key: data.key, value: data.value, shared: true };
    },
    async set(key, value) {
      const res = await fetch(base, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key, value }),
      });
      if (!res.ok) throw new Error("storage set failed");
      const data = await res.json();
      return { key: data.key, value: data.value, shared: true };
    },
    async delete(key) {
      const res = await fetch(`${base}?key=${encodeURIComponent(key)}`, { method: "DELETE" });
      if (!res.ok) throw new Error("storage delete failed");
      return { key, deleted: true, shared: true };
    },
    async list(prefix = "") {
      const res = await fetch(`${base}?prefix=${encodeURIComponent(prefix)}`);
      if (!res.ok) throw new Error("storage list failed");
      const data = await res.json();
      return { keys: data.keys, shared: true };
    },
  };
}

