/* ===================== STORAGE HOOK ===================== */
function useShopData() {
  const [designs, setDesigns] = useState(seedDesigns);
  const [artists, setArtists] = useState(seedArtists);
  const [prices, setPrices] = useState(seedPrices);
  const [categories, setCategories] = useState(CATEGORIES);
  const [promo, setPromo] = useState(seedPromo);
  const [bookings, setBookings] = useState([]);
  const [reviews, setReviews] = useState(seedReviews);
  const [messages, setMessages] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const shop = await window.storage.get("codeink:shop", true);
        if (shop && shop.value) {
          const parsed = JSON.parse(shop.value);
          if (parsed.designs) setDesigns(parsed.designs);
          if (parsed.artists) setArtists(parsed.artists);
          if (parsed.prices) setPrices(parsed.prices);
          if (parsed.categories) setCategories(parsed.categories);
          if (parsed.promo) setPromo(parsed.promo);
        }
      } catch (e) { /* no data yet, seed defaults remain */ }
      try {
        const b = await window.storage.get("codeink:bookings", true);
        if (b && b.value) setBookings(JSON.parse(b.value));
      } catch (e) {}
      try {
        const r = await window.storage.get("codeink:reviews", true);
        if (r && r.value) setReviews(JSON.parse(r.value));
      } catch (e) {}
      try {
        const m = await window.storage.get("codeink:messages", true);
        if (m && m.value) setMessages(JSON.parse(m.value));
      } catch (e) {}
      setLoaded(true);
    })();
  }, []);

  const persistShop = async (next) => {
    try {
      const res = await window.storage.set("codeink:shop", JSON.stringify({
        designs: next.designs ?? designs,
        artists: next.artists ?? artists,
        prices: next.prices ?? prices,
        categories: next.categories ?? categories,
        promo: next.promo ?? promo,
      }), true);
      return !!res;
    } catch (e) { console.error("storage error", e); return false; }
  };

  const warnIfFailed = (ok) => {
    if (!ok) {
      window.alert(
        "This change wasn't saved to the server and will revert on refresh.\n\n" +
        "This usually means the site's shared storage isn't connected yet " +
        "(e.g. Vercel KV isn't set up or its environment variables aren't linked to this deployment)."
      );
    }
  };

  const updateDesigns = async (next) => { setDesigns(next); warnIfFailed(await persistShop({ designs: next })); };
  const updateArtists = async (next) => { setArtists(next); warnIfFailed(await persistShop({ artists: next })); };
  const updatePrices = async (next) => { setPrices(next); warnIfFailed(await persistShop({ prices: next })); };
  const updateCategories = async (next) => { setCategories(next); warnIfFailed(await persistShop({ categories: next })); };
  const updatePromo = async (next) => { setPromo(next); warnIfFailed(await persistShop({ promo: next })); };

  const addBooking = async (booking) => {
    const next = [...bookings, booking];
    setBookings(next);
    try {
      const res = await window.storage.set("codeink:bookings", JSON.stringify(next), true);
      warnIfFailed(!!res);
    } catch (e) { warnIfFailed(false); }
  };
  const updateBookings = async (next) => {
    setBookings(next);
    try {
      const res = await window.storage.set("codeink:bookings", JSON.stringify(next), true);
      warnIfFailed(!!res);
    } catch (e) { warnIfFailed(false); }
  };
  const addReview = async (review) => {
    const next = [...reviews, review];
    setReviews(next);
    try {
      const res = await window.storage.set("codeink:reviews", JSON.stringify(next), true);
      warnIfFailed(!!res);
    } catch (e) { warnIfFailed(false); }
  };
  const updateReviews = async (next) => {
    setReviews(next);
    try {
      const res = await window.storage.set("codeink:reviews", JSON.stringify(next), true);
      warnIfFailed(!!res);
    } catch (e) { warnIfFailed(false); }
  };
  const addMessage = async (msg) => {
    const next = [...messages, msg];
    setMessages(next);
    try {
      const res = await window.storage.set("codeink:messages", JSON.stringify(next), true);
      warnIfFailed(!!res);
    } catch (e) { warnIfFailed(false); }
  };
  const updateMessages = async (next) => {
    setMessages(next);
    try {
      const res = await window.storage.set("codeink:messages", JSON.stringify(next), true);
      warnIfFailed(!!res);
    } catch (e) { warnIfFailed(false); }
  };

  return {
    loaded, designs, artists, prices, categories, promo, bookings, reviews, messages,
    updateDesigns, updateArtists, updatePrices, updateCategories, updatePromo,
    addBooking, updateBookings, addReview, updateReviews, addMessage, updateMessages,
  };
}

/* ===================== PROMO BANNER ===================== */
function PromoBanner({ promo, setPage, setGalleryFilter }) {
  if (!promo || !promo.active) return null;
  return (
    <div className="ck-promo">
      <div className="ck-promo-tag"><Sparkles size={13} /> Limited promo</div>
      <h3>{promo.title}</h3>
      <p>{promo.subtitle}</p>
      <div className="ck-promo-actions">
        <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={() => { setGalleryFilter && setGalleryFilter("Minimalist"); setPage("Gallery"); }}>
          Browse minimalist designs <ArrowRight size={14} />
        </button>
        <button className="ck-btn ck-btn-outline ck-btn-sm" onClick={() => setPage("Booking")}>Book this promo</button>
      </div>
      {promo.terms && <span className="ck-promo-terms">{promo.terms}</span>}
    </div>
  );
}

