/* ===================== CALCULATOR ===================== */
function Calculator({ prices, setPage, setBookingPrefill }) {
  const [size, setSize] = useState("s1");
  const [complexity, setComplexity] = useState("Simple");
  const [placement, setPlacement] = useState("Forearm / Bicep");
  const [qty, setQty] = useState("1");

  const tier = prices.find(p => p.size === size) || prices[0];
  const hasBundle = tier && tier.bundleQty;

  useEffect(() => { if (!hasBundle) setQty("1"); }, [size]);

  const isBundle = qty === "bundle" && hasBundle;
  const estimate = isBundle
    ? tier.bundlePrice
    : Math.round((tier?.price || 0) * COMPLEXITY_MULT[complexity] * PLACEMENT_MULT[placement]);

  return (
    <div className="ck-section">
      <h1 className="ck-page-title">Price Calculator</h1>
      <p className="ck-page-sub">Get an instant estimate before you book. Final pricing is confirmed at consultation.</p>
      <div className="ck-calc-layout">
        <div className="ck-calc-form">
          <Field label="Size">
            <select value={size} onChange={(e) => setSize(e.target.value)}>
              {prices.map(p => <option key={p.size} value={p.size}>{p.label}{p.plusOnly ? " (starting)" : ""}</option>)}
            </select>
          </Field>
          {hasBundle && (
            <Field label="How many">
              <select value={qty} onChange={(e) => setQty(e.target.value)}>
                <option value="1">1 tattoo</option>
                <option value="bundle">{tier.bundleQty} tattoos (bundle deal)</option>
              </select>
            </Field>
          )}
          <Field label="Complexity">
            <select value={complexity} onChange={(e) => setComplexity(e.target.value)} disabled={isBundle}>
              {Object.keys(COMPLEXITY_MULT).map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </Field>
          <Field label="Placement">
            <select value={placement} onChange={(e) => setPlacement(e.target.value)} disabled={isBundle}>
              {Object.keys(PLACEMENT_MULT).map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </Field>
        </div>
        <div className="ck-calc-result">
          <span className="ck-mono">Estimated price</span>
          <div className="ck-calc-number">₱{estimate}{tier?.plusOnly && !isBundle ? "+" : ""}</div>
          <p className="ck-calc-fine">
            {isBundle
              ? `Bundle deal: ${tier.bundleQty} pieces at ${tier.label}, flat price.`
              : `Based on ${tier?.label}, ${complexity.toLowerCase()} detail, ${placement.toLowerCase()}.`}
          </p>
          <button className="ck-btn ck-btn-primary" onClick={() => {
            setBookingPrefill({ size: tier?.label, placement, estimate, bundle: isBundle ? tier.bundleQty : null });
            setPage("Booking");
          }}>
            Book with this estimate <ArrowRight size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}

