/* ===================== BOOKING ===================== */
function Booking({ designs, artists, addBooking, prefill, setPrefill }) {
  const [mode, setMode] = useState(prefill ? "existing" : "existing");
  const [designId, setDesignId] = useState("");
  const [customDesc, setCustomDesc] = useState("");
  const [size, setSize] = useState(prefill?.size || "3-4 in");
  const [placement, setPlacement] = useState(prefill?.placement || "");
  const [artistId, setArtistId] = useState("");
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [notes, setNotes] = useState("");
  const [fileName, setFileName] = useState("");
  const [submitted, setSubmitted] = useState(false);

  const canSubmit = name && email && date && time && (mode === "existing" ? designId : customDesc);

  const submit = () => {
    if (!canSubmit) return;
    addBooking({
      id: "b" + Date.now(),
      mode,
      designTitle: mode === "existing" ? (designs.find(d => d.id === designId)?.title || "") : customDesc,
      size, placement, artist: artists.find(a => a.id === artistId)?.name || "No preference",
      date, time, name, email, phone, notes,
      referenceFile: fileName || null,
      status: "Pending",
      createdAt: new Date().toISOString(),
    });
    setSubmitted(true);
    setPrefill(null);
  };

  if (submitted) {
    return (
      <div className="ck-section ck-confirm">
        <Check size={40} color="#39FF6A" />
        <h1>Booking request sent</h1>
        <p>CODEINK will review your request and confirm your appointment by email within 24–48 hours. A deposit link will be included in your confirmation.</p>
      </div>
    );
  }

  return (
    <div className="ck-section">
      <h1 className="ck-page-title">Book an Appointment</h1>
      <p className="ck-page-sub">Choose a design or request something custom, then tell us the details.</p>

      <div className="ck-chips">
        <button className={`ck-chip ${mode === "existing" ? "is-active" : ""}`} onClick={() => setMode("existing")}>Choose a design</button>
        <button className={`ck-chip ${mode === "custom" ? "is-active" : ""}`} onClick={() => setMode("custom")}>Request custom tattoo</button>
      </div>

      <div className="ck-booking-form">
        {mode === "existing" ? (
          <Field label="Design">
            <select value={designId} onChange={(e) => setDesignId(e.target.value)}>
              <option value="">Select a design</option>
              {designs.map(d => <option key={d.id} value={d.id}>{d.title} — {d.category}</option>)}
            </select>
          </Field>
        ) : (
          <Field label="Describe your custom idea">
            <textarea value={customDesc} onChange={(e) => setCustomDesc(e.target.value)} rows={3}
              placeholder="Concept, references, cover-up details, etc." />
          </Field>
        )}

        <div className="ck-form-row">
          <Field label="Size">
            <select value={size} onChange={(e) => setSize(e.target.value)}>
              {["1-2 in", "3-4 in", "5-6 in", "7 in +"].map(s => <option key={s}>{s}</option>)}
            </select>
          </Field>
          <Field label="Placement">
            <input value={placement} onChange={(e) => setPlacement(e.target.value)} placeholder="e.g. Left forearm" />
          </Field>
        </div>

        <div className="ck-form-row">
          <Field label="Preferred artist">
            <select value={artistId} onChange={(e) => setArtistId(e.target.value)}>
              <option value="">No preference</option>
              {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
            </select>
          </Field>
          <Field label="Reference image">
            <div className="ck-upload">
              <Upload size={15} />
              <span>{fileName || "Choose file"}</span>
              <input type="file" onChange={(e) => setFileName(e.target.files?.[0]?.name || "")} />
            </div>
          </Field>
        </div>

        <div className="ck-form-row">
          <Field label="Preferred date">
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
          </Field>
          <Field label="Preferred time">
            <input type="time" value={time} onChange={(e) => setTime(e.target.value)} />
          </Field>
        </div>

        <div className="ck-form-row">
          <Field label="Full name">
            <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name" />
          </Field>
          <Field label="Email">
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@email.com" />
          </Field>
        </div>
        <Field label="Phone">
          <input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="(555) 555-5555" />
        </Field>
        <Field label="Notes for your artist">
          <textarea value={notes} onChange={(e) => setNotes(e.target.value)} rows={2} placeholder="Allergies, availability, questions..." />
        </Field>

        <button className="ck-btn ck-btn-primary" disabled={!canSubmit} onClick={submit}>
          Submit booking request <ArrowRight size={16} />
        </button>
        {!canSubmit && <span className="ck-form-hint">Name, email, date, time, and a design or custom description are required.</span>}
      </div>
    </div>
  );
}

