function AdminDesigns({ shop }) {
  const blank = { id: "", title: "", category: shop.categories[0], size: "3-4 in", price: 100, placement: "", desc: "", image: "" };
  const [editing, setEditing] = useState(null);

  const save = () => {
    if (!editing.title) return;
    const exists = shop.designs.some(d => d.id === editing.id);
    const next = exists ? shop.designs.map(d => d.id === editing.id ? editing : d) : [...shop.designs, { ...editing, id: "d" + Date.now() }];
    shop.updateDesigns(next);
    setEditing(null);
  };
  const remove = (id) => shop.updateDesigns(shop.designs.filter(d => d.id !== id));

  return (
    <div>
      <div className="ck-admin-head">
        <h2>Designs ({shop.designs.length})</h2>
        <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={() => setEditing(blank)}><Plus size={14} /> Add design</button>
      </div>
      {editing && (
        <div className="ck-admin-form">
          <div className="ck-form-row">
            <Field label="Title"><input value={editing.title} onChange={(e) => setEditing({ ...editing, title: e.target.value })} /></Field>
            <Field label="Category">
              <select value={editing.category} onChange={(e) => setEditing({ ...editing, category: e.target.value })}>
                {shop.categories.map(c => <option key={c}>{c}</option>)}
              </select>
            </Field>
          </div>
          <div className="ck-form-row">
            <Field label="Size"><input value={editing.size} onChange={(e) => setEditing({ ...editing, size: e.target.value })} /></Field>
            <Field label="Price (₱, 0 = quote)"><input type="number" value={editing.price} onChange={(e) => setEditing({ ...editing, price: Number(e.target.value) })} /></Field>
          </div>
          <Field label="Placement suggestions"><input value={editing.placement} onChange={(e) => setEditing({ ...editing, placement: e.target.value })} /></Field>
          <Field label="Description"><textarea rows={2} value={editing.desc} onChange={(e) => setEditing({ ...editing, desc: e.target.value })} /></Field>
          <Field label="Photo URL (optional — leave blank to use generated art)">
            <input value={editing.image || ""} onChange={(e) => setEditing({ ...editing, image: e.target.value })} placeholder="https://..." />
          </Field>
          {editing.image && (
            <img src={editing.image} alt="preview" style={{ width: 120, height: 120, objectFit: "cover", borderRadius: 4, border: "1px solid var(--ck-line)" }} />
          )}
          <div className="ck-form-row">
            <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={save}>Save design</button>
            <button className="ck-btn ck-btn-outline ck-btn-sm" onClick={() => setEditing(null)}>Cancel</button>
          </div>
        </div>
      )}
      <div className="ck-admin-list">
        {shop.designs.map(d => (
          <div key={d.id} className="ck-admin-row">
            <div><strong>{d.title}</strong><span className="ck-mono"> · {d.category} · {d.size} · {d.price ? `₱${d.price}` : "quote"}</span></div>
            <div className="ck-row-actions">
              <button onClick={() => setEditing(d)}><Pencil size={14} /></button>
              <button onClick={() => remove(d.id)}><Trash2 size={14} /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminPromo({ shop }) {
  const [draft, setDraft] = useState(shop.promo);
  useEffect(() => setDraft(shop.promo), [shop.promo]);
  return (
    <div>
      <div className="ck-admin-head"><h2>Promo banner</h2></div>
      <div className="ck-admin-form">
        <Field label="Active">
          <select value={draft.active ? "yes" : "no"} onChange={(e) => setDraft({ ...draft, active: e.target.value === "yes" })}>
            <option value="yes">Shown on site</option>
            <option value="no">Hidden</option>
          </select>
        </Field>
        <Field label="Title"><input value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} /></Field>
        <Field label="Subtitle"><textarea rows={2} value={draft.subtitle} onChange={(e) => setDraft({ ...draft, subtitle: e.target.value })} /></Field>
        <Field label="Terms / fine print"><textarea rows={2} value={draft.terms} onChange={(e) => setDraft({ ...draft, terms: e.target.value })} /></Field>
        <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={() => shop.updatePromo(draft)}>Save promo</button>
      </div>
      <div className="ck-note">
        <Sparkles size={16} />
        <span>This banner appears on the Home page and at the top of the Gallery when filtered to Minimalist.</span>
      </div>
    </div>
  );
}

function AdminCategories({ shop }) {
  const [newCat, setNewCat] = useState("");
  const add = () => {
    if (!newCat.trim() || shop.categories.includes(newCat.trim())) return;
    shop.updateCategories([...shop.categories, newCat.trim()]);
    setNewCat("");
  };
  const remove = (c) => shop.updateCategories(shop.categories.filter(x => x !== c));
  return (
    <div>
      <div className="ck-admin-head"><h2>Categories ({shop.categories.length})</h2></div>
      <div className="ck-form-row">
        <input value={newCat} onChange={(e) => setNewCat(e.target.value)} placeholder="New category name" />
        <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={add}><Plus size={14} /> Add</button>
      </div>
      <div className="ck-admin-list">
        {shop.categories.map(c => (
          <div key={c} className="ck-admin-row">
            <span>{c}</span>
            <button onClick={() => remove(c)}><Trash2 size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminPrices({ shop }) {
  const update = (size, key, val) => {
    shop.updatePrices(shop.prices.map(p => p.size === size ? { ...p, [key]: Number(val) } : p));
  };
  return (
    <div>
      <div className="ck-admin-head"><h2>Prices (₱)</h2></div>
      <div className="ck-table-wrap">
        <table className="ck-table ck-table-edit">
          <thead>
            <tr><th>Size</th><th>Price</th><th>Bundle qty</th><th>Bundle price</th><th>Starting-price only</th></tr>
          </thead>
          <tbody>
            {shop.prices.map(row => (
              <tr key={row.size}>
                <td className="ck-table-style">{row.label}</td>
                <td><input type="number" value={row.price} onChange={(e) => update(row.size, "price", e.target.value)} /></td>
                <td><input type="number" value={row.bundleQty || 0} onChange={(e) => update(row.size, "bundleQty", e.target.value)} /></td>
                <td><input type="number" value={row.bundlePrice || 0} onChange={(e) => update(row.size, "bundlePrice", e.target.value)} /></td>
                <td>
                  <select value={row.plusOnly ? "yes" : "no"} onChange={(e) => shop.updatePrices(shop.prices.map(p => p.size === row.size ? { ...p, plusOnly: e.target.value === "yes" } : p))}>
                    <option value="no">No</option>
                    <option value="yes">Yes</option>
                  </select>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="ck-note">
        <ShieldCheck size={16} />
        <span>Set bundle qty/price to 0 to hide the bundle deal for that size. "Starting-price only" shows a "+" and hides bundle options on that tier.</span>
      </div>
    </div>
  );
}

function AdminArtists({ shop }) {
  const blank = { id: "", name: "", specialty: "", bio: "", pieces: 0 };
  const [editing, setEditing] = useState(null);
  const save = () => {
    if (!editing.name) return;
    const exists = shop.artists.some(a => a.id === editing.id);
    const next = exists ? shop.artists.map(a => a.id === editing.id ? editing : a) : [...shop.artists, { ...editing, id: "a" + Date.now() }];
    shop.updateArtists(next);
    setEditing(null);
  };
  const remove = (id) => shop.updateArtists(shop.artists.filter(a => a.id !== id));
  return (
    <div>
      <div className="ck-admin-head">
        <h2>Artists ({shop.artists.length})</h2>
        <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={() => setEditing(blank)}><Plus size={14} /> Add artist</button>
      </div>
      {editing && (
        <div className="ck-admin-form">
          <div className="ck-form-row">
            <Field label="Name"><input value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field>
            <Field label="Specialty"><input value={editing.specialty} onChange={(e) => setEditing({ ...editing, specialty: e.target.value })} /></Field>
          </div>
          <Field label="Bio"><textarea rows={2} value={editing.bio} onChange={(e) => setEditing({ ...editing, bio: e.target.value })} /></Field>
          <Field label="Pieces tattooed"><input type="number" value={editing.pieces} onChange={(e) => setEditing({ ...editing, pieces: Number(e.target.value) })} /></Field>
          <div className="ck-form-row">
            <button className="ck-btn ck-btn-primary ck-btn-sm" onClick={save}>Save artist</button>
            <button className="ck-btn ck-btn-outline ck-btn-sm" onClick={() => setEditing(null)}>Cancel</button>
          </div>
        </div>
      )}
      <div className="ck-admin-list">
        {shop.artists.map(a => (
          <div key={a.id} className="ck-admin-row">
            <div><strong>{a.name}</strong><span className="ck-mono"> · {a.specialty}</span></div>
            <div className="ck-row-actions">
              <button onClick={() => setEditing(a)}><Pencil size={14} /></button>
              <button onClick={() => remove(a.id)}><Trash2 size={14} /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminBookings({ shop }) {
  const setStatus = (id, status) => shop.updateBookings(shop.bookings.map(b => b.id === id ? { ...b, status } : b));
  return (
    <div>
      <div className="ck-admin-head"><h2>Bookings ({shop.bookings.length})</h2></div>
      {shop.bookings.length === 0 && <p className="ck-empty">No booking requests yet.</p>}
      <div className="ck-admin-list">
        {[...shop.bookings].reverse().map(b => (
          <div key={b.id} className="ck-booking-row">
            <div className="ck-booking-main">
              <strong>{b.name}</strong>
              <span className="ck-mono">{b.email} · {b.phone || "no phone"}</span>
              <span>{b.designTitle} · {b.size} · {b.placement || "placement TBD"}</span>
              <span className="ck-mono">{b.date} at {b.time} · artist: {b.artist}</span>
              {b.referenceFile && <span className="ck-mono">Reference: {b.referenceFile}</span>}
              {b.notes && <span className="ck-notes">"{b.notes}"</span>}
            </div>
            <div className="ck-booking-status">
              <span className={`ck-status ck-status-${b.status.toLowerCase()}`}>{b.status}</span>
              <div className="ck-row-actions">
                <button className="ck-btn ck-btn-sm ck-btn-primary" onClick={() => setStatus(b.id, "Approved")}>Approve</button>
                <button className="ck-btn ck-btn-sm ck-btn-outline" onClick={() => setStatus(b.id, "Declined")}>Decline</button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminReviews({ shop }) {
  const toggle = (id) => shop.updateReviews(shop.reviews.map(r => r.id === id ? { ...r, approved: !r.approved } : r));
  const remove = (id) => shop.updateReviews(shop.reviews.filter(r => r.id !== id));
  return (
    <div>
      <div className="ck-admin-head"><h2>Reviews ({shop.reviews.length})</h2></div>
      <div className="ck-admin-list">
        {shop.reviews.map(r => (
          <div key={r.id} className="ck-admin-row">
            <div>
              <strong>{r.name}</strong> <StarRow n={r.rating} />
              <p className="ck-notes">"{r.text}"</p>
            </div>
            <div className="ck-row-actions">
              <button onClick={() => toggle(r.id)}>{r.approved ? "Unapprove" : "Approve"}</button>
              <button onClick={() => remove(r.id)}><Trash2 size={14} /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminMessages({ shop }) {
  const remove = (id) => shop.updateMessages(shop.messages.filter(m => m.id !== id));
  return (
    <div>
      <div className="ck-admin-head"><h2>Customer messages ({shop.messages.length})</h2></div>
      {shop.messages.length === 0 && <p className="ck-empty">No messages yet.</p>}
      <div className="ck-admin-list">
        {[...shop.messages].reverse().map(m => (
          <div key={m.id} className="ck-admin-row">
            <div>
              <strong>{m.name}</strong> <span className="ck-mono">{m.email}</span>
              <p className="ck-notes">{m.message}</p>
            </div>
            <button onClick={() => remove(m.id)}><Trash2 size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

